'use strict';
const $=s=>document.querySelector(s);
const icons={star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',book:'M12 5v16M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-2-1-6-2-10 1z',scroll:'M6 3h13v16a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-2h12v2a2 2 0 0 0 4 0M6 3a3 3 0 0 0-3 3v2h5V6a3 3 0 0 0-2-3M8 3v14M11 8h5M11 12h5',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16M8 14h2M14 14h2M8 18h2',chest:'M3 10h18v10H3zM3 10V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v3M3 13h18M10 11h4v5h-4z',shirt:'M8 3l-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4c0 4-8 4-8 0z',door:'M5 21V3h14v18M9 21V6l8-2v17M12 13h1',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v10M9 9h5M10 15h5',gem:'M3 8l5-5h8l5 5-9 13zM3 8h18M8 3l4 18 4-18',trophy:'M7 3h10v5c0 5-10 5-10 0zM7 5H3v3c0 3 4 4 6 4M17 5h4v3c0 3-4 4-6 4M12 12v7M7 21h10M9 19h6',arrow:'M4 12h16M14 6l6 6-6 6',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',check:'M5 12l4 4L19 6',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',music:'M9 18V5l11-2v13M9 9l11-2M9 18c0 4-6 4-6 1s6-4 6-1M20 16c0 4-6 4-6 1s6-4 6-1',logout:'M9 3H4v18h5M12 12h10M17 7l5 5-5 5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',home:'M2 11L12 2l10 9M5 9v12h14V9M9 21v-8h6v8',sparkle:'M12 2l2 7 7 3-7 2-2 8-3-8-7-2 7-3z'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.star}"/></svg>`}
const heroes=[{name:'森之劍士',en:'FOREST KNIGHT',desc:'帶住勇氣出發，每一小步都值得驕傲。',gear:'初心者之劍',color:'森綠披風'},{name:'星語魔法師',en:'STAR MAGE',desc:'好奇心就係你最強大嘅魔法。',gear:'星光法杖',color:'星語魔法帽'},{name:'月光學者',en:'MOON SCHOLAR',desc:'每翻開一頁，都會發現新世界。',gear:'月光筆記',color:'學者長袍'},{name:'翠葉遊俠',en:'LEAF RANGER',desc:'專注眼前嘅目標，慢慢就會到達。',gear:'翠葉短弓',color:'森林斗篷'},];
const KEY='starlight-study-v1';
function initial(){return {hero:0,nickname:'小小冒險者',xp:0,crystals:0,chests:0,treasures:[],equipped:null,totalMinutes:0,quests:[{id:'q1',title:'森林文字結界',detail:'中文 · 重溫第六課默書詞語',minutes:15,xp:30,subject:'中文',date:today(),done:false},{id:'q2',title:'魔法數字的秘密',detail:'數學 · 完成乘數練習',minutes:20,xp:40,subject:'數學',date:today(),done:false},{id:'q3',title:'古代語言碎片',detail:'英文 · 串讀 Unit 3 生字',minutes:10,xp:25,subject:'英文',date:today(),done:false}],events:[]}}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
let data;try{data=JSON.parse(localStorage.getItem(KEY))||initial()}catch{data=initial()}
migrateCrystalCurrency(data);
if(data.hero!==null && (!Number.isInteger(data.hero)||data.hero<0||data.hero>=heroes.length))data.hero=0;
let page='landing',role='child',chosen=data.hero??0,modal=null,timer=null,roomInterval=null,musicOn=false,audioCtx=null,musicNodes=[],storageNotice=false;
let sessionRole=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{if(!storageNotice){storageNotice=true;notify('瀏覽器未能儲存進度，今次仍可繼續試玩。')}}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function level(){return Math.floor(data.xp/100)+1}
function heroStyle(i){return `background-position:${(i%3)*50}% ${Math.floor(i/3)*100}%`}
function portrait(i,cls='portrait'){return `<div class="${cls}" style="${heroStyle(i)}" aria-hidden="true"></div>`}
function brand(){return `<div class="brand">${icon('sparkle')}<div>星光冒險<small>STARLIGHT CHRONICLE</small></div></div>`}
function backdrop(){return `<div class="scenery"></div><div class="grain"></div>${[12,35,63,83,91].map((x,i)=>`<i class="firefly" style="left:${x}%;top:${35+i*9}%;animation-delay:${i*.8}s"></i>`).join('')}`}
function soundButton(){return `<button class="nav-pill" data-action="sound" aria-label="${musicOn?'關閉':'開啟'}音樂" aria-pressed="${musicOn}">${icon('music')}<span class="sound-label">音樂${musicOn?'開':'關'}</span></button>`}
function landing(){return `<main class="screen landing">${backdrop()}<header class="topbar">${brand()}${soundButton()}</header><div class="landing-content"><div class="eyebrow">A LITTLE EFFORT. A GRAND ADVENTURE.</div><h1>星光冒險</h1><div class="en-title">Starlight Chronicle</div><div class="ornament">✧</div><p class="landing-copy">每一分努力，都會成為你的光。<br>翻開故事，展開屬於你的成長冒險。</p><button class="primary gold start" data-action="start">開始冒險 ${icon('arrow')}</button><p class="keyhint">PRESS ANY KEY TO START</p></div><div class="chapter-tag"><p>YOUR STORY BEGINS HERE</p><h3>第一章 · 森林裡的小屋</h3></div><footer class="landing-footer"><span>為每一位努力中的小小勇者而設</span><span>學習 × 冒險 × 成長 <span class="version"> · PROTOTYPE 01</span></span></footer></main>`}
function login(){return `<main class="screen">${backdrop()}<header class="topbar">${brand()}<button class="nav-pill" data-action="landing">${icon('home')} 返回開場</button></header><div class="login-layout"><div class="login-intro"><div class="eyebrow">WELCOME HOME, ADVENTURER</div><h1>你的故事，<br>由這裡繼續。</h1><p>一盞燈、一張書枱，還有未完的冒險。<br>小屋已經準備好，等你回來。</p></div><section class="paper login-card"><p class="section-kicker">THE ADVENTURER'S GATE</p><h2>歡迎返嚟</h2><p class="subtle">選擇你的身份，打開冒險之門。</p><div class="role-tabs" role="group" aria-label="登入身份"><button data-role="child" class="${role==='child'?'active':''}" aria-pressed="${role==='child'}">小朋友登入<br><small>Children Login</small></button><button data-role="parent" class="${role==='parent'?'active':''}" aria-pressed="${role==='parent'}">家長登入<br><small>Parents Login</small></button></div><form id="login-form"><label class="field" for="username">冒險者帳戶</label><input class="input" id="username" name="username" autocomplete="username" placeholder="${role==='child'?'test':'admin'}" required><label class="field" for="password">通行密語</label><input class="input" id="password" name="password" type="password" autocomplete="current-password" placeholder="輸入密碼" required><p class="error" id="login-error" role="alert"></p><button class="primary" type="submit">${role==='child'?'進入冒險小屋':'進入公會管理室'} ${icon('arrow')}</button></form><p class="demo-note">測試版帳戶 · ${role==='child'?'test / test':'admin / admin'}<br>此版本使用示範登入，進度只儲存於目前瀏覽器。</p></section></div></main>`}
function characterSelect(change=false){return `<main class="paper-screen screen"><header class="topbar">${brand()}<button class="nav-pill" data-action="${change?'room':'logout'}">${icon(change?'home':'logout')} ${change?'返回小屋':'登出'}</button></header><div class="page-heading"><p class="section-kicker">CHOOSE YOUR ADVENTURER</p><h1>${change?'今天，想以什麼模樣冒險？':'每個故事，都需要一位勇者。'}</h1><p class="subtle">四位勇者，同一份勇氣。揀一位陪你成長嘅伙伴。</p></div><div class="characters">${heroes.map((h,i)=>`<button class="char-card ${chosen===i?'selected':''}" data-hero="${i}" aria-pressed="${chosen===i}"><span class="char-check">${icon('check')}</span>${portrait(i)}<h3>${h.name}</h3><p>${h.en}</p></button>`).join('')}</div><div class="selection-bottom"><p class="selection-description" id="hero-desc">${heroes[chosen].desc}</p><label class="field" for="nickname">你的冒險者名字</label><input class="input" id="nickname" maxlength="16" value="${esc(data.nickname)}" aria-label="冒險者名字"><button class="primary" data-action="confirm-hero">${change?'換好裝，返屋企':'準備好，展開冒險'} ${icon('arrow')}</button><p class="subtle">角色外觀可以隨時更改，所有角色獲得相同學習獎勵。</p></div></main>`}
function room(){const done=data.quests.filter(q=>q.done).length;return `<main class="screen room">${backdrop()}<header class="topbar"><div class="statusbar"><button class="player-pill" data-action="stats" aria-label="查看角色狀態">${portrait(data.hero,'mini-portrait')}<span class="player-info"><strong>${esc(data.nickname)} <span style="color:#9c895f">Lv.${level()}</span></strong><small>${heroes[data.hero].name} · ${data.xp%data.xpPerLevel}/${data.xpPerLevel} EXP</small><span class="xpbar"><span style="width:${(data.xp%data.xpPerLevel)/data.xpPerLevel*100}%"></span></span></span></button><span class="currency">${icon('gem')} ${data.crystals}</span></div><div class="bottom-nav">${soundButton()}<button class="nav-pill" data-action="logout" aria-label="登出">${icon('logout')}</button></div></header><div class="room-welcome"><div class="eyebrow">HOME, SWEET HOME</div><h1>歡迎返嚟，${esc(data.nickname)}。</h1><p>今天的小小努力，就是明天的魔法。</p></div><button class="hotspot h-quest" data-action="quests">${icon('scroll')} 任務板 <span class="badge">${data.quests.length-done}</span></button><button class="hotspot h-calendar" data-action="calendar">${icon('calendar')} 冒險日曆</button><button class="hotspot h-study" data-action="study">${icon('book')} 溫習書枱</button><button class="hotspot h-wardrobe" data-action="wardrobe">${icon('shirt')} 角色衣櫃</button><button class="hotspot h-chest" data-action="treasure">${icon('chest')} 寶物收藏</button><button class="hotspot h-door" data-action="quests">${icon('door')} 出發冒險</button><div id="room-actor" class="room-actor" style="left:51%;top:72%"><div class="actor-bubble" id="actor-bubble">返到屋企喇！</div><div class="actor-shadow"></div><div class="actor-body">${portrait(data.hero,'actor-sprite')}</div><div class="actor-prop" id="actor-prop"></div></div><footer class="room-footer"><button class="today-card" data-action="quests">${icon('sun')}<span><h3>今日的冒險 · 已完成 ${done} / ${data.quests.length}</h3><p>${done===data.quests.length?'好叻！今日嘅任務全部完成。':'撳屋內嘅傢俬，發現你嘅下一個任務。'}</p></span>${icon('arrow')}</button><div class="room-chapter">第一章 · 森林裡的小屋<br><button class="nav-pill" data-action="achievements">${icon('trophy')} 成就手冊</button></div></footer><button class="achievement-mobile nav-pill" data-action="achievements" aria-label="成就手冊">${icon('trophy')}</button></main>`}
function admin(){return `<main class="paper-screen screen"><header class="topbar">${brand()}<button class="nav-pill" data-action="logout">${icon('logout')} 登出</button></header><div class="admin-wrap"><p class="section-kicker">THE GUILD MASTER'S ROOM</p><h1 class="serif" style="margin-top:12px">公會管理室</h1><p class="subtle" style="margin-top:10px">將每日嘅學習，變成值得期待嘅冒險。</p><div class="stats"><div class="stat"><b>${data.quests.filter(q=>q.done).length}</b><small>已完成任務</small></div><div class="stat"><b>${data.totalMinutes}</b><small>累積專注分鐘</small></div><div class="stat"><b>${level()}</b><small>冒險者等級</small></div></div><div class="admin-columns"><section class="paper admin-panel"><h2>派發新任務</h2><p class="subtle">小朋友會喺小屋嘅任務板收到。</p><form id="quest-form"><label class="field" for="quest-title">冒險任務名稱</label><input class="input" id="quest-title" name="title" maxlength="40" placeholder="例如：解開森林文字結界" required><label class="field" for="quest-detail">實際學習內容</label><input class="input" id="quest-detail" name="detail" maxlength="160" placeholder="例如：溫習中文第六課詞語" required><div class="form-grid"><div><label class="field" for="quest-subject">科目</label><select class="input" id="quest-subject" name="subject"><option>中文</option><option>英文</option><option>數學</option><option>常識</option><option>閱讀</option><option>其他</option></select></div><div><label class="field" for="quest-minutes">專注時間（分鐘）</label><input class="input" id="quest-minutes" name="minutes" type="number" min="1" max="120" value="15" required></div><div><label class="field" for="quest-date">目標日期</label><input class="input" id="quest-date" name="date" type="date" value="${today()}" required></div><div><label class="field" for="quest-xp">經驗值獎勵</label><input class="input" id="quest-xp" name="xp" type="number" min="5" max="100" value="30" required></div></div><div class="form-end"><button class="primary" type="submit">${icon('scroll')} 發佈任務</button></div></form></section><section class="paper admin-panel"><h2>冒險者任務記錄</h2><div id="admin-quests">${questRows(true)}</div></section></div><p class="demo-note">測試版：家長與小朋友需使用同一瀏覽器，才能共用任務及進度。示範帳戶並非正式身份驗證。</p></div></main>`}
function questRows(parent=false){return data.quests.length?data.quests.map(q=>`<div class="quest-row ${q.done?'completed':''}"><span class="quest-symbol">${icon(q.done?'check':'scroll')}</span><div class="quest-text"><h3>${esc(q.title)}</h3><p>${esc(q.detail)}<br>${q.minutes} 分鐘 · +${q.xp} EXP · ${esc(q.date)}</p>${q.help?'<p style="color:#a66f42">小朋友需要幫手重溫</p>':''}</div>${q.done?'<span class="checkmark">已完成</span>':parent?`<button class="ghost small-btn danger" data-delete="${q.id}">移除</button>`:`<button class="primary small-btn" data-quest="${q.id}">出發 ${icon('arrow')}</button>`}</div>`).join(''):'<p class="empty">任務板暫時空白。<br>可以由家長登入新增任務。</p>'}
function statsBody(){const h=heroes[data.hero];return `<div class="player-stats"><div class="stats-character">${portrait(data.hero)}<h3>${esc(data.nickname)}</h3><p class="subtle">${h.name}</p></div><div class="stats-details"><p class="section-kicker">PLAYER STATISTICS</p><div class="level-display">Lv. ${level()} <small>初心冒險者</small></div><p class="subtle">經驗值 ${data.xp%data.xpPerLevel} / ${data.xpPerLevel}</p><div class="xpbar large"><span style="width:${(data.xp%data.xpPerLevel)/data.xpPerLevel*100}%"></span></div><div class="resource-grid"><div>${icon('gem')}<strong>${data.crystals}</strong><small>水晶</small></div><div>${icon('chest')}<strong>${data.chests}</strong><small>寶箱</small></div><div>${icon('trophy')}<strong>${unlockedAchievements()}</strong><small>成就</small></div></div><p class="section-kicker" style="margin:22px 0 12px">EQUIPMENT · 裝備</p><div class="equipment-row">${icon('shield')}<span>${esc(data.equipped||h.gear)}<small>武器 · ${data.equipped?'森林珍品':'初始裝備'}</small></span><span class="equipment-tag">已裝備</span></div><div class="equipment-row">${icon('shirt')}<span>${h.color}<small>服飾 · 初始裝備</small></span><span class="equipment-tag">已裝備</span></div></div></div><div class="inline-actions" style="margin-top:20px"><button class="ghost small-btn" data-action="treasure">${icon('chest')} 寶物收藏</button><button class="ghost small-btn" data-action="achievements">${icon('trophy')} 成就手冊</button></div>`}
const achievements=[{name:'故事的第一頁',desc:'建立你嘅冒險者角色。',test:()=>data.hero!==null,icon:'star'},{name:'踏出第一步',desc:'完成第一個學習任務。',test:()=>data.quests.some(q=>q.done),icon:'scroll'},{name:'專注的微光',desc:'累積專注 30 分鐘。',test:()=>data.totalMinutes>=30,icon:'clock'},{name:'成長的力量',desc:'冒險者等級達到 Lv.2。',test:()=>level()>=2,icon:'shield'},{name:'尋寶小勇者',desc:'打開第一個獎勵寶箱。',test:()=>data.chests>=1,icon:'chest'},{name:'星光收藏家',desc:'累積獲得 10 顆水晶。',test:()=>data.crystals>=10,icon:'gem'}];
function unlockedAchievements(){return achievements.filter(a=>a.test()).length}
function achievementBody(){return `<p class="subtle">每一段成長，都值得留低紀念。已解鎖 ${unlockedAchievements()} / ${achievements.length}</p><div class="achievement-grid">${achievements.map(a=>`<div class="achievement-item ${a.test()?'unlocked':'locked'}"><span class="achievement-emblem">${icon(a.icon)}</span><h3>${a.name}</h3><p>${a.desc}</p><small>${a.test()?'已解鎖':'尚未解鎖'}</small></div>`).join('')}</div>`}
function treasureBody(){const pending=data.quests.filter(q=>q.done).length-data.chests;return `<p class="subtle">完成任務就可以獲得寶箱，每個寶箱有 5 顆水晶及一件森林紀念物。</p><div class="treasure-feature">${icon('chest')}<h3>${pending>0?`有 ${pending} 個寶箱等你打開`:'寶箱正等待下一次冒險'}</h3><button class="primary" data-action="open-chest" ${pending>0?'':'disabled'}>打開寶箱 ${icon('sparkle')}</button></div><h3 style="font-size:16px;margin:20px 0 10px">我的寶物 · ${data.treasures.length}</h3>${data.treasures.length?data.treasures.map((t,i)=>`<div class="equipment-row">${icon('gem')}<span>${esc(t.name)}<small>${esc(t.desc)}</small></span><button class="ghost small-btn" data-equip="${i}" ${data.equipped===t.name?'disabled':''}>${data.equipped===t.name?'已裝備':'裝備'}</button></div>`).join(''):'<p class="empty">第一件寶物，就藏喺下一個任務之後。</p>'}`}
function calendarBody(){const grouped={};data.quests.forEach(q=>(grouped[q.date]??=[]).push(q));return `<p class="subtle">將大目標，拆成每日做得到嘅小步。日期以香港時間顯示。</p>${Object.keys(grouped).sort().map(d=>`<div class="calendar-event"><strong>${esc(d)} ${d===today()?'· 今日':''}</strong>${grouped[d].map(q=>`<p>${q.done?'✓':'○'} ${esc(q.title)} · ${q.minutes} 分鐘</p>`).join('')}</div>`).join('')||'<p class="empty">暫時未有安排。</p>'}<p class="subtle">家長可以喺管理室新增任務及設定目標日期。</p>`}
function openModal(kind,body,title){modal=kind;const old=$('.overlay');if(old)old.remove();const el=document.createElement('div');el.className='overlay';el.innerHTML=`<section class="paper modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><p class="section-kicker">STARLIGHT CHRONICLE</p><h2 id="modal-title">${title}</h2></div><button class="close" data-action="close" aria-label="關閉">×</button></header>${body}</section>`;document.body.append(el);el.querySelector('button')?.focus();}
let lastFocus=null;
function show(kind){if(sessionRole!=='child')return;lastFocus=document.activeElement;const opts={stats:[statsBody,'冒險者狀態'],quests:[()=>`<p class="subtle">選一個任務出發，慢慢累積你嘅星光。</p>${questRows()}`,'今日任務'],study:[()=>`<p class="subtle">準備好課本同文具，揀一個任務，專心出發。</p>${questRows()}`,'溫習書枱'],calendar:[calendarBody,'冒險日曆'],achievements:[achievementBody,'成就手冊'],treasure:[treasureBody,'寶物收藏']};if(opts[kind])openModal(kind,opts[kind][0](),opts[kind][1]);}
function closeModal(){if(timer){notify('請先暫停並儲存，或者繼續完成任務。');return}$('.overlay')?.remove();modal=null;lastFocus?.focus();}
function render(){if(roomInterval){clearInterval(roomInterval);roomInterval=null}$('.overlay')?.remove();modal=null;$('#app').innerHTML=({landing,login,select:()=>characterSelect(data.hero!==null),room,admin}[page]||landing)();if(page==='room')startRoomAnimation()}
function go(p){if(timer){notify('請先儲存目前嘅溫習進度。');return}page=p;render()}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(notify.handle);notify.handle=setTimeout(()=>t.classList.remove('visible'),3600)}
function startRoomAnimation(){const activities=[{x:30,y:72,action:'reading',text:'睇多一頁，發現新世界。',prop:'book'},{x:52,y:76,action:'greeting',text:'今日都一齊努力！',prop:'sparkle'},{x:69,y:79,action:'stretching',text:'伸個懶腰，充充電～',prop:'sun'},{x:48,y:69,action:'thinking',text:'下一個冒險會係點呢？',prop:'star'},{x:61,y:79,action:'resting',text:'休息一下，再出發。',prop:'moon'}];let a=0;function next(){if(modal)return;const el=$('#room-actor');if(!el)return;const v=activities[a++%activities.length];const oldX=parseFloat(el.style.left);el.className=`room-actor walking ${v.x<oldX?'facing-left':''}`;el.style.left=v.x+'%';el.style.top=v.y+'%';$('#actor-bubble').classList.remove('show');$('#actor-prop').innerHTML='';setTimeout(()=>{if(!document.contains(el))return;el.className=`room-actor ${v.action}`;$('#actor-bubble').textContent=v.text;$('#actor-bubble').classList.add('show');$('#actor-prop').innerHTML=v.prop==='moon'?'<span class="zzz">z Z</span>':icon(v.prop)},2600)}setTimeout(()=>{if(page==='room')next()},1200);roomInterval=setInterval(next,8500)}
function elapsed(){if(!timer)return 0;return Math.min(timer.total,timer.acc+(timer.running?Math.max(0,(Date.now()-timer.started)/1000):0))}
function formatTime(s){s=Math.max(0,Math.ceil(s));return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`}
function startQuest(id){const q=data.quests.find(q=>q.id===id);if(!q||q.done||sessionRole!=='child')return;let saved=data.timerDraft?.id===id?data.timerDraft.acc:0;timer={id,total:q.minutes*60,acc:Math.min(saved,q.minutes*60),running:true,started:Date.now()};drawTimer();timer.handle=setInterval(tickTimer,500)}
function drawTimer(){const q=data.quests.find(q=>q.id===timer.id);openModal('timer',`<div class="timer-panel"><p class="subtle">${esc(q.detail)}</p><div class="journey"><div class="journey-label">${esc(q.title)} · 專心溫習，伙伴陪你前進</div><div class="walker" id="timer-walker">${portrait(data.hero)}</div></div><div class="timer-number" id="timer-clock">${formatTime(timer.total-elapsed())}</div><p class="subtle" id="timer-note">準備好課本，將注意力放喺眼前嘅學習。</p><div class="inline-actions" style="margin-top:24px"><button class="primary" data-action="pause" id="pause-btn">暫停休息</button><button class="ghost" data-action="save-timer">儲存並返回</button></div><div id="timer-finish"></div></div>`,'專注冒險');tickTimer()}
function tickTimer(){if(!timer)return;const e=elapsed();$('#timer-clock').textContent=formatTime(timer.total-e);$('#timer-walker').style.left=`${5+e/timer.total*70}%`;if(e>=timer.total){timer.acc=timer.total;timer.running=false;clearInterval(timer.handle);$('#pause-btn').disabled=true;$('#timer-note').textContent='時間到！記錄一下今次完成咗幾多。';$('#timer-finish').innerHTML=`<p class="subtle" style="margin:22px 0 12px">計時完成代表投入過時間。你覺得今次進度點？</p><div class="inline-actions"><button class="primary small-btn" data-finish="complete">已完成任務</button><button class="ghost small-btn" data-finish="partial">做咗一部分</button><button class="ghost small-btn" data-finish="help">有啲地方唔明</button></div>`}}
function saveTimer(){if(!timer)return;data.timerDraft={id:timer.id,acc:elapsed()};clearInterval(timer.handle);timer=null;persist();closeModal();notify('已保留專注進度，下次可以繼續。')}
function finishQuest(mode){if(!timer||elapsed()<timer.total)return;const q=data.quests.find(q=>q.id===timer.id);clearInterval(timer.handle);timer=null;data.timerDraft=null;if(mode==='complete'){if(!q.done){q.done=true;data.xp+=q.xp;data.crystals+=Math.round(q.xp/2);data.totalMinutes+=q.minutes}persist();render();show('treasure');notify(`任務完成！+${q.xp} EXP，獲得一個寶箱。`)}else{q.help=mode==='help';data.totalMinutes+=q.minutes;persist();render();show('quests');notify(mode==='help'?'已記錄需要幫手，家長可以喺任務記錄睇到。':'已記錄投入時間，任務保留，下次繼續。')}}
function toggleMusic(){musicOn=!musicOn;if(musicOn){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const gain=audioCtx.createGain();gain.gain.value=.018;gain.connect(audioCtx.destination);[130.81,196,261.63,329.63].forEach((f,i)=>{const osc=audioCtx.createOscillator();osc.type='sine';osc.frequency.value=f;const g=audioCtx.createGain();g.gain.value=.35;osc.connect(g);g.connect(gain);osc.start();musicNodes.push(osc)});}catch{musicOn=false;notify('此瀏覽器暫時未能播放音樂。')}}else{musicNodes.forEach(n=>n.stop());musicNodes=[]}document.querySelectorAll('[data-action="sound"]').forEach(b=>{b.setAttribute('aria-pressed',musicOn);b.setAttribute('aria-label',musicOn?'關閉音樂':'開啟音樂');b.innerHTML=`${icon('music')}<span class="sound-label">音樂${musicOn?'開':'關'}</span>`})}
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.role){role=target.dataset.role;go('login');return}if(target.dataset.hero!==undefined){chosen=Number(target.dataset.hero);document.querySelectorAll('.char-card').forEach((c,i)=>{c.classList.toggle('selected',i===chosen);c.setAttribute('aria-pressed',i===chosen)});$('#hero-desc').textContent=heroes[chosen].desc;return}if(target.dataset.quest){startQuest(target.dataset.quest);return}if(target.dataset.finish){finishQuest(target.dataset.finish);return}if(target.dataset.delete&&sessionRole==='parent'){data.quests=data.quests.filter(q=>q.id!==target.dataset.delete);persist();render();return}if(target.dataset.equip!==undefined){data.equipped=data.treasures[Number(target.dataset.equip)]?.name;persist();show('treasure');notify('已換上新裝備。');return}const a=target.dataset.action;if(!a)return;if(['stats','quests','calendar','study','treasure','achievements'].includes(a)){show(a);return}switch(a){case'start':go('login');break;case'landing':go('landing');break;case'logout':sessionRole=null;go('login');break;case'room':if(sessionRole==='child')go('room');break;case'wardrobe':chosen=data.hero;go('select');break;case'confirm-hero':{if(sessionRole!=='child')break;data.hero=chosen;data.nickname=$('#nickname').value.trim()||'小小冒險者';persist();go('room');break}case'close':closeModal();break;case'sound':toggleMusic();break;case'pause':if(timer){if(timer.running){timer.acc=elapsed();timer.running=false;$('#pause-btn').textContent='繼續冒險';$('#timer-note').textContent='休息一下，準備好再繼續。'}else{timer.started=Date.now();timer.running=true;$('#pause-btn').textContent='暫停休息';$('#timer-note').textContent='將注意力放喺眼前嘅學習。'}}break;case'save-timer':saveTimer();break;case'open-chest':{if(data.quests.filter(q=>q.done).length<=data.chests)break;const items=[{name:'森林琥珀吊墜',desc:'記錄你第一份努力嘅溫暖琥珀。'},{name:'星光羽毛筆',desc:'每一個認真寫下嘅字，都閃閃發光。'},{name:'晨露水晶',desc:'藏住清晨第一道光嘅小小寶石。'}];data.treasures.push(items[data.chests%items.length]);data.chests++;data.crystals+=5;persist();render();show('treasure');notify('寶箱打開！獲得 5 顆水晶同一件寶物。');break}}});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='login-form'){const u=f.get('username').trim(),p=f.get('password');if(role==='parent'&&u==='admin'&&p==='admin'){sessionRole='parent';go('admin')}else if(role==='child'&&u==='test'&&p==='test'){sessionRole='child';go(data.hero===null?'select':'room')}else{$('#login-error').textContent='帳戶或密碼不正確，請確認登入身份。'}}else if(e.target.id==='quest-form'&&sessionRole==='parent'){const title=f.get('title').trim(),detail=f.get('detail').trim();if(!title||!detail)return;data.quests.push({id:crypto.randomUUID(),title,detail,subject:f.get('subject'),minutes:Number(f.get('minutes')),xp:Number(f.get('xp')),date:f.get('date'),done:false});persist();render();notify('新任務已送到小朋友嘅任務板。')}});
document.addEventListener('keydown',e=>{if(page==='landing'&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&!['Tab','Shift','Control','Alt','Meta','Escape'].includes(e.key)){e.preventDefault();go('login');return}if(e.key==='Escape'&&modal){closeModal();return}if(e.key==='Tab'&&modal){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('storage',e=>{if(e.key===KEY&&!timer){try{const updated=JSON.parse(e.newValue);if(updated){data=updated;render()}}catch{}}});
window.addEventListener('beforeunload',()=>{if(timer){data.timerDraft={id:timer.id,acc:elapsed()};persist()}});
render();
